import*as THREE from'three';import{Component,Port,materials}from'../../core/index.js';import{roundedRect}from'../../core/geometry.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import data from'./geometry-data.js';import{addStickers}from'./stickers.js';
const tau=Math.PI*2;
function board(host){const s=new THREE.Shape(),x=10.35,r=3.6,a=Math.acos((x-8)/r),dy=Math.sqrt(r*r-(x-8)**2),cy=-6;s.moveTo(-5.5,-16.5);s.lineTo(-8.7,-16.5);s.lineTo(-x,-14.8);s.lineTo(-x,cy-dy);s.absarc(-8,cy,r,Math.PI+a,Math.PI-a,false);s.lineTo(-x,9.7);s.lineTo(-8.7,11.5);s.lineTo(8.7,11.5);s.lineTo(x,9.7);s.lineTo(x,cy+dy);s.absarc(8,cy,r,a,tau-a,false);s.lineTo(x,-14.8);s.lineTo(8.7,-16.5);s.lineTo(5.5,-16.5);s.lineTo(5.5,-11.5);s.lineTo(-5.5,-11.5);s.closePath();const bore=new THREE.Path();bore.absarc(0,-6,1.8,0,tau,false);s.holes.push(bore);const pcb=mesh(host.body,new THREE.ExtrudeGeometry(s,{depth:.8,bevelEnabled:false,curveSegments:48}),materials.plastic(0x35442c,{roughness:.92}),[0,0,-2.1],'OP180 physical fixed PCB with true retaining bore and mounting reliefs');pcb.userData={role:'physical-pcb',inferred:true};const passive=materials.plastic(0x33372e,{roughness:.86}),ceramic=materials.plastic(0xb4a174,{roughness:.86}),metal=materials.metal(0xb2b6a6,{roughness:.46}),passives=[];for(const[n,x,y,w,h]of[['R1 1K',-4.5,6.2,1.6,.8],['R2 20K',4.5,6.2,1.6,.8],['R3 10K',4.5,3.8,1.6,.8],['C4 100nF',-4.5,3.8,1.6,.8],['C5 100nF',0,1.6,1.6,.8]]){const p=slab(host.body,w,h,.5,.05,[x,y,-1.3],n.startsWith('C')?ceramic:passive,[],.01);p.name='OP180 fixed '+n;passives.push(p);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.22,h,.2),metal,[x+sign*(w/2-.06),y,-1.18],'OP180 passive physical solder termination');}return{pcb,passives};}
function optointerrupter(host){const dark=materials.plastic(0x151a19,{roughness:.72}),glass=materials.plastic(0x29282d,{roughness:.35}),die=materials.plastic(0x0b0d10,{roughness:.5}),metal=materials.metal(0xb8b5a5,{roughness:.45});const arms=[],caps=[],windows=[],dies=[];const crossbar=mesh(host.body,new THREE.BoxGeometry(14,2,6),dark,[0,11.5,1.8],'OP180 fixed ITR9606 lower crossbar below open detection slot');crossbar.userData={role:'physical-optical-package',part:'ITR9606',inferred:true};for(const sign of[-1,1]){const shape=roundedRect(6,5.5,.08),hole=roundedRect(1.5,1.4,.12,{cx:0,cy:.05,path:new THREE.Path(),clockwise:false});shape.holes.push(hole);const geometry=new THREE.ExtrudeGeometry(shape,{depth:4.2,bevelEnabled:false,curveSegments:32});geometry.rotateY(Math.PI/2);const arm=mesh(host.body,geometry,dark,[sign<0?-6.7:2.5,15.25,1.8],'OP180 fixed '+(sign<0?'left':'right')+' ITR9606 arm with true recessed optical aperture');arm.userData={role:'physical-optical-arm',inferred:true};arms.push(arm);caps.push(mesh(host.body,new THREE.BoxGeometry(.3,5.5,6),dark,[sign*6.85,15.25,1.8],'OP180 ITR9606 outer opaque arm cap'));const w=mesh(host.body,new THREE.BoxGeometry(.12,1.25,1.35),glass,[sign*2.62,15.3,1.8],'OP180 recessed passive '+(sign<0?'emitter':'receiver')+' window');w.userData={role:'passive-optical-window',visibleEmission:false,handednessInferred:true};windows.push(w);dies.push(mesh(host.body,new THREE.BoxGeometry(.15,1.32,1.4),die,[sign*3.05,15.3,1.8],'OP180 deep non-emissive optical die backing'));for(const z of[-.15,.15])mesh(host.body,new THREE.BoxGeometry(.6,.35,.12),dark,[sign*6.98,12.9,1.8+z*6],'OP180 fixed package moulding ridge');}const leads=[];for(const x of[-5.3,-3.7,3.7,5.3]){leads.push(mesh(host.body,new THREE.BoxGeometry(.4,2.1,.25),metal,[x,10,-1.13],'OP180 physical ITR9606 solder lead '+(leads.length+1)));mesh(host.body,new THREE.BoxGeometry(.4,.35,.7),metal,[x,10.9,-.83],'OP180 bent optical package lead riser');}return{arms,caps,crossbar,windows,dies,leads};}
function grove(host){const frame=new THREE.Group();frame.name='OP180 physical black HY2.0-4P socket';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const black=materials.plastic(spec.grove.color,{roughness:.74}),metal=materials.metal(0xb7b6a3,{roughness:.42}),box=(s,p,n,m=black)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'OP180 Grove '+n),depth=6.1;for(const sign of[-1,1]){box([.65,5.2,depth],[sign*4.675,0,-depth/2],'side rail');box([.7,.6,3.2],[sign*3.85,2.3,-4.5],'inner guide');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'locking shoulder');}box([8.7,.65,depth],[0,-2.275,-depth/2],'floor');box([8.7,4.55,.65],[0,.325,-depth+.325],'deep dielectric rear wall');box([4.8,.45,2.3],[0,2.375,-4.3],'locking bridge');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.3],[(i-1.5)*2,.2,-3.5],'real contact '+(i+1),metal));box([.42,1.3,.42],[(i-1.5)*2,-2.65,-5.6],'solder tail '+(i+1),metal);}const port=host.add(new Port({id:'grove',label:'Digital output · HY2.0-4P',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'NC',color:'yellow'},{n:4,name:'IN',color:'white'}],meta:{role:'visual-connector',face:'bottom',scope:'Four physical contacts and cable attachment/pose only;IN is the own rear-label marking;no optical counting,logic,electrical,power or protocol behavior'}}));return{frame,contacts,port};}
export function buildOp180(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe9eae3,{roughness:.8})}),pcb=board(host),sensor=optointerrupter(host),input=grove(host),fixing=screw(host.body,[0,-6,-3.84],'back',1.25);fixing.name='OP180 recessed central fixed retaining screw';mesh(host.body,new THREE.CylinderGeometry(.6,.6,3.9,32).rotateX(Math.PI/2),materials.metal(0x9a9f95),[0,-6,-1.85],'OP180 concealed fixed retaining screw shank');const back=slab(host.body,16,12,.05,.08,[0,5,-3.85],materials.plastic(0xe1e2dc,{roughness:.88}),[],.005);back.name='OP180 physical rear adhesive label substrate';back.userData={role:'physical-label-substrate',face:'back'};const anchor=host.add(new Component({id:'sensor',label:'ITR9606 fixed open-slot appearance anchor',position:spec.sensor.position,meta:{role:'visual-anchor',part:'ITR9606',fixedAngleDeg:180,slotWidthMm:spec.sensor.slotWidthMm,slotDepthMm:spec.sensor.slotDepthMm,openDirection:spec.sensor.openDirection,emitterPosition:spec.sensor.emitterPosition,receiverPosition:spec.sensor.receiverPosition,emitterOutward:spec.sensor.emitterOutward,receiverOutward:spec.sensor.receiverOutward,handednessInferred:true,scope:'Passive fixed opposing optical appearance only;180 is product orientation,not a movable joint;no beam,visible emission,occlusion,count,value,level,IR,detection,register,electrical,power or firmware behavior'}}));host.op180Assembly={parts,pcb,sensor,input,fixing,labels:{back},anchor};host.unitStickers=addStickers(host);}
